head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil45101";
scwin.engMandatory1YnCnt = 0;
scwin.otherFormObj = undefined;
scwin.viewWin = null;
scwin.goWrite = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — submittedDocumentList, writingDocumentList
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.corpUsrTpCd

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_submittedDocumentList", fn: function(){ return ((String(((dma_pageContext.get("submittedDocumentList") ?? "")) == null ? '' : ((dma_pageContext.get("submittedDocumentList") ?? ""))).length === 0)); } }, { id: "c_otherwise_61", fn: function(){ return (!(((() => { throw new Error("unresolved:data:" + "doc.docType"); })() === '1'))); } }, { id: "c_when_65_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.langTpCd"); })() === '1'); } }, { id: "c_otherwise_66", fn: function(){ return (!(((() => { throw new Error("unresolved:data:" + "doc.langTpCd"); })() === '1'))); } }, { id: "if_writingDocumentList", fn: function(){ return ((String(((dma_pageContext.get("writingDocumentList") ?? "")) == null ? '' : ((dma_pageContext.get("writingDocumentList") ?? ""))).length === 0)); } }, { id: "btn_goWrite", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'F'); } }, { id: "btn_goViewer_2", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'M'); } }, { id: "btn_goViewer_3", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'A'); } }, { id: "c_when_79", fn: function(){ return ((dma_subdoc.get("docNo") ?? (() => { throw new Error("unresolved:" + "subdoc.docNo"); })()) === '00000000000000'); } }, { id: "c_otherwise_87", fn: function(){ return (!(((dma_subdoc.get("docNo") ?? (() => { throw new Error("unresolved:" + "subdoc.docNo"); })()) === '00000000000000'))); } }, { id: "if_disclsTitle_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsTitle"); })() !== ''); } }, { id: "if_wrtrptMaindocTpCd", fn: function(){ return ((dma_subdoc.get("wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "c_otherwise_96", fn: function(){ return (!(((dma_subdoc.get("wrtYn") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtYn"); })()) === 'Y'))); } }, { id: "if_wrtrptMaindocTpCd_2", fn: function(){ return ((dma_subdoc.get("wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '2'); } }, { id: "if_wrtrptMaindocTpCd_3", fn: function(){ return ((dma_subdoc.get("wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '1'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_56", entity: "dlt_submittedDocumentList", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return "- (영문)" + String(v("formKorNm")); } }, { childId: "__rc1", fn: function (v, i) { return "- " + String(v("formKorNm")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("disclsProcsStatNm")); } }, { childId: "__rc3", fn: function (v, i) { return String(v("disclsProcsDdTm")); } }, { childId: "__rc4", fn: function (v, i) { return String(v("disclsAcptTpNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb5", fn: function () { return " " + String(dma_subdoc.get("formKorNm")) + " " + String(dma_subdoc.get("formEngNm")); } },
        { childId: "__rb6", fn: function () { return "(" + String(dlt_submittedDocumentList.getCellData(0, "disclsTitle")) + ")"; } },
        { childId: "__rb7", fn: function () { return dlt_submittedDocumentList.getCellData(0, "lstChgDdtm"); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["corpUsrTpCd"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil45101' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.goWrite = goWrite;
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil45101.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_submitSearchForm_onclick
 * @description btn_submitSearchForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_submitSearchForm_onclick = function(e){
    try {
        scwin.submitSearchForm()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil45101.btn_submitSearchForm_onclick' }); }
};

/**
 * @method
 * @name btn_goViewer_onclick
 * @description btn_goViewer 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goViewer_onclick = function(e){
    try {
        scwin.goViewer((String(((() => { throw new Error("unresolved:data:" + "doc.acptNo"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "doc.acptNo"); })())).indexOf('$' + '{') >= 0 ? '' : String(((() => { throw new Error("unresolved:data:" + "doc.acptNo"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "doc.acptNo"); })()))))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil45101.btn_goViewer_onclick' }); }
};

/**
 * @method
 * @name btn_goViewer_2_onclick
 * @description btn_goViewer_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goViewer_2_onclick = function(e){
    try {
        scwin.goViewer((String(((() => { throw new Error("unresolved:data:" + "doc.modOrgnDisclsAcptNo"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "doc.modOrgnDisclsAcptNo"); })())).indexOf('$' + '{') >= 0 ? '' : String(((() => { throw new Error("unresolved:data:" + "doc.modOrgnDisclsAcptNo"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "doc.modOrgnDisclsAcptNo"); })()))),'' + dma_subdoc.get("formCd") + '','' + dma_subdoc.get("formVer") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil45101.btn_goViewer_2_onclick' }); }
};

/**
 * @method
 * @name btn_goViewer_3_onclick
 * @description btn_goViewer_3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goViewer_3_onclick = function(e){
    try {
        scwin.goViewer((String(((() => { throw new Error("unresolved:data:" + "doc.addOrgnDisclsAcptNo"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "doc.addOrgnDisclsAcptNo"); })())).indexOf('$' + '{') >= 0 ? '' : String(((() => { throw new Error("unresolved:data:" + "doc.addOrgnDisclsAcptNo"); })()) == null ? '' : ((() => { throw new Error("unresolved:data:" + "doc.addOrgnDisclsAcptNo"); })()))),'' + dma_subdoc.get("formCd") + '','' + dma_subdoc.get("formVer") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil45101.btn_goViewer_3_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_goViewer2
 * @description go Viewer2 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goViewer2 = async function () {
    try { return await $c.data.downFile("/submission/disclosure.do?method=searchDisclosureContentPrint", "", ($c.util.getComponent("dma_goViewer2Req") ? $c.util.getComponent("dma_goViewer2Req").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_goWriteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_loadListReq",
        target: "dlt_submittedDocumentList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goViewer
 * @description go Viewer 처리
 * @param {*} acptNo acptNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @returns {void}
 * @hidden N
 */
scwin.goViewer = function (acptNo, formCd, formVer) {
    fn_Disclsviewer(acptNo);
};

/**
 * @method
 * @name goViewer2
 * @description go Viewer2 처리
 * @param {*} acptNo acptNo
 * @param {*} applNo applNo
 * @param {String} statCd statCd
 * @param {String} langTpCd langTpCd
 * @param {String} tgtIsurCd tgtIsurCd
 * @param {*} tgtFssUnqNo tgtFssUnqNo
 * @param {String} tgtComNm tgtComNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goViewer2 = async function (acptNo, applNo, statCd, langTpCd, tgtIsurCd, tgtFssUnqNo, tgtComNm) {
    if (statCd === '30') {
        fn_Disclsviewer(acptNo);
    } else {
        scwin.viewWin = $c.win.openPopup("", { id: "viewWin", scrollbars: true, resizable: true, width: "700", height: "550", type: "pageFramePopup" }, {});
        $c.util.getComponent('dma_goViewer2Req').set('applNo', applNo);
        $c.util.getComponent('dma_goViewer2Req').set('langTpCd', langTpCd);
        $c.util.getComponent('dma_goViewer2Req').set('tgtIsurCd', tgtIsurCd);
        $c.util.getComponent('dma_goViewer2Req').set('tgtFssUnqNo', tgtFssUnqNo);
        $c.util.getComponent('dma_goViewer2Req').set('tgtComNm', tgtComNm);
        (document.viewerFrm || { elements: [] }).target = 'viewWin';
        (document.viewerFrm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureContentPrint';
        await scwin.tx_fn_goViewer2();
    }
};

async function goWrite(applNo, disclsMaindocFormCd, disclsMaindocFormVer, currFormVer, currEngFormVer, beforeFormVer, beforeEngFormVer, oldFormVerUseYn, docNo, formCd, formVer, langTpCd, tgtIsurCd, tgtFssUnqNo, disclsAcptTpCd, wrtrptMaindocTpCd, disclsObjCorpIsurNm, subcomDisclsYn, formUpclssCd, tgtComEngNm, disclsObjRepIsuSrtCd, engMandatory1Yn) {
    (document.writeForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument';
    $c.util.getComponent('dma_goViewer2Req').set('applNo', applNo);
    if (engMandatory1Yn === "Y" && scwin.engMandatory1YnCnt === 0 && '11' === (String(($c.session.getUserInfo("corpUsrTpCd")) == null ? '' : ($c.session.getUserInfo("corpUsrTpCd"))).indexOf('$' + '{') >= 0 ? '' : String(($c.session.getUserInfo("corpUsrTpCd")) == null ? '' : ($c.session.getUserInfo("corpUsrTpCd"))))) {
        alertEngMandatory1();
        $("#alertEngMandatory1_close").attr("onclick", "javascript:goWrite('" + applNo + "','" + disclsMaindocFormCd + "','" + disclsMaindocFormVer + "','" + currFormVer + "','" + currEngFormVer + "','" + beforeFormVer + "','" + beforeEngFormVer + "','" + oldFormVerUseYn + "','" + docNo + "','" + formCd + "','" + formVer + "','" + langTpCd + "','" + tgtIsurCd + "','" + tgtFssUnqNo + "','" + disclsAcptTpCd + "','" + wrtrptMaindocTpCd + "','" + disclsObjCorpIsurNm + "','" + subcomDisclsYn + "','" + formUpclssCd + "','" + tgtComEngNm + "','" + disclsObjRepIsuSrtCd + "','" + engMandatory1Yn + "')");
        scwin.engMandatory1YnCnt++;
        return;
    }
    if (docNo !== '00000000000000') {
        $c.util.getComponent('dma_goViewer2Req').set('docNo', docNo);
    }
    if (langTpCd === '0') {
        if (disclsAcptTpCd === 'F' || (disclsAcptTpCd === 'M' && docNo !== '00000000000000')) {
            if (oldFormVerUseYn === 'Y') {
                if (disclsMaindocFormVer !== currFormVer && disclsMaindocFormVer !== beforeFormVer) {
                    if (await $c.win.confirm('* 서식버전이 변경되어 더이상 유효하지 않습니다. \n* 새문서로 작성하여 제출하시기 바랍니다. \n* 내용을 보시겠습니까?.')) {
                        $c.util.getComponent('dma_goViewer2Req').set('applNo', applNo);
                        $c.util.getComponent('dma_goViewer2Req').set('tgtIsurCd', tgtIsurCd);
                        $c.util.getComponent('dma_goViewer2Req').set('tgtFssUnqNo', tgtFssUnqNo);
                        $c.util.getComponent('dma_goViewer2Req').set('tgtIsuSrtCd', disclsObjRepIsuSrtCd);
                        $c.util.getComponent('dma_goViewer2Req').set('tgtComNm', disclsObjCorpIsurNm);
